import React, { useMemo, useState } from "react";
import { Background, Controls, MiniMap, ReactFlow } from "reactflow";
import "reactflow/dist/style.css";

import {
  workers,
  partitions,
  topologyStatus,
} from "../data/mockData";

// import "./Topology.css";


/* ============================================================
   CUSTOM NODES
   ============================================================ */

function KafkaNode() {
  return (
    <div className="topology-custom-node">

      <div className="topology-node-title">
        Kafka
      </div>

      <div className="topology-node-subtitle">
        truck-telemetry
      </div>

      <div className="topology-node-status">
        <span className="topology-status-dot healthy" />
        {topologyStatus.kafka.status}
      </div>

      <div className="topology-node-info">
        {partitions.length} partitions
      </div>

    </div>
  );
}


function ProcessorNode() {
  const healthyWorkers = workers.filter(
    (worker) => worker.status === "healthy"
  ).length;

  return (
    <div className="topology-custom-node">

      <div className="topology-node-title">
        Stream Processor
      </div>

      <div className="topology-node-subtitle">
        Bytewax / Faust
      </div>

      <div className="topology-node-status">
        <span className="topology-status-dot healthy" />
        {topologyStatus.processor.status}
      </div>

      <div className="topology-node-info">
        {healthyWorkers}/{workers.length} workers healthy
      </div>

    </div>
  );
}


function AggregationNode() {
  return (
    <div className="topology-custom-node">

      <div className="topology-node-title">
        Temperature Aggregation
      </div>

      <div className="topology-node-subtitle">
        5-minute window
      </div>

      <div className="topology-node-info">
        Filter: temperature &gt; 0
      </div>

    </div>
  );
}


function RocksDBNode() {
  return (
    <div className="topology-custom-node">

      <div className="topology-node-title">
        RocksDB
      </div>

      <div className="topology-node-subtitle">
        Local State Store
      </div>

      <div className="topology-node-status">
        <span className="topology-status-dot healthy" />
        {topologyStatus.rocksdb.status}
      </div>

    </div>
  );
}


function PrometheusNode() {
  return (
    <div className="topology-custom-node">

      <div className="topology-node-title">
        Prometheus
      </div>

      <div className="topology-node-subtitle">
        Metrics
      </div>

      <div className="topology-node-status">
        <span className="topology-status-dot healthy" />
        {topologyStatus.prometheus.status}
      </div>

    </div>
  );
}


function UINode() {
  return (
    <div className="topology-custom-node">

      <div className="topology-node-title">
        StreamForge UI
      </div>

      <div className="topology-node-subtitle">
        Monitoring Dashboard
      </div>

      <div className="topology-node-status">
        <span className="topology-status-dot healthy" />
        Online
      </div>

    </div>
  );
}


/* ============================================================
   NODE TYPES
   ============================================================ */

const nodeTypes = {
  kafka: KafkaNode,
  processor: ProcessorNode,
  aggregation: AggregationNode,
  rocksdb: RocksDBNode,
  prometheus: PrometheusNode,
  ui: UINode,
};


/* ============================================================
   TOPOLOGY PAGE
   ============================================================ */

export default function Topology() {

  const [showMinimap, setShowMinimap] = useState(true);


  /* ==========================================================
     DERIVED TOPOLOGY INFORMATION
     ========================================================== */

  const healthyWorkers = useMemo(
    () =>
      workers.filter(
        (worker) => worker.status === "healthy"
      ).length,
    []
  );


  const failedWorkers = useMemo(
    () =>
      workers.filter(
        (worker) => worker.status === "failed"
      ).length,
    []
  );


  const activePartitions = useMemo(
    () =>
      partitions.filter(
        (partition) => partition.status === "active"
      ).length,
    []
  );


  /* ==========================================================
     REACT FLOW NODES
     ========================================================== */

  const nodes = useMemo(
    () => [

      {
        id: "kafka",
        type: "kafka",
        position: {
          x: 50,
          y: 180,
        },
        draggable: true,
      },

      {
        id: "processor",
        type: "processor",
        position: {
          x: 320,
          y: 180,
        },
        draggable: true,
      },

      {
        id: "aggregation",
        type: "aggregation",
        position: {
          x: 600,
          y: 180,
        },
        draggable: true,
      },

      {
        id: "rocksdb",
        type: "rocksdb",
        position: {
          x: 600,
          y: 360,
        },
        draggable: true,
      },

      {
        id: "prometheus",
        type: "prometheus",
        position: {
          x: 880,
          y: 360,
        },
        draggable: true,
      },

      {
        id: "ui",
        type: "ui",
        position: {
          x: 1160,
          y: 360,
        },
        draggable: true,
      },

    ],
    []
  );


  /* ==========================================================
     REACT FLOW EDGES
     ========================================================== */

  const edges = useMemo(
    () => [

      {
        id: "kafka-processor",
        source: "kafka",
        target: "processor",
        animated: true,
      },

      {
        id: "processor-aggregation",
        source: "processor",
        target: "aggregation",
        animated: true,
      },

      {
        id: "processor-rocksdb",
        source: "processor",
        target: "rocksdb",
        animated: false,
        style: {
          strokeDasharray: "6 4",
        },
      },

      {
        id: "processor-prometheus",
        source: "processor",
        target: "prometheus",
        animated: false,
        style: {
          strokeDasharray: "6 4",
        },
      },

      {
        id: "prometheus-ui",
        source: "prometheus",
        target: "ui",
        animated: false,
        style: {
          strokeDasharray: "6 4",
        },
      },

    ],
    []
  );


  return (
    <div className="topology-page">

      {/* =====================================================
          HEADER
      ====================================================== */}

      <div className="topology-page-header">

        <div>
          <h1>Topology</h1>

          <p>
            Detailed StreamForge processing architecture.
          </p>
        </div>

      </div>


      {/* =====================================================
          SUMMARY
      ====================================================== */}

      <div className="topology-summary">

        <div className="topology-summary-card">

          <span>Workers</span>

          <strong>
            {healthyWorkers}/{workers.length}
          </strong>

          <small>
            healthy
          </small>

        </div>


        <div className="topology-summary-card">

          <span>Partitions</span>

          <strong>
            {activePartitions}/{partitions.length}
          </strong>

          <small>
            active
          </small>

        </div>


        <div className="topology-summary-card">

          <span>Processor</span>

          <strong>
            {topologyStatus.processor.status}
          </strong>

          <small>
            Bytewax / Faust
          </small>

        </div>


        <div className="topology-summary-card">

          <span>Worker Failures</span>

          <strong>
            {failedWorkers}
          </strong>

          <small>
            detected
          </small>

        </div>

      </div>


      {/* =====================================================
          TOOLBAR
      ====================================================== */}

      <div className="topology-toolbar">

        <button
          className="topology-minimap-button"
          onClick={() =>
            setShowMinimap((value) => !value)
          }
        >
          {showMinimap
            ? "Hide Minimap"
            : "Show Minimap"}
        </button>

      </div>


      {/* =====================================================
          GRAPH
      ====================================================== */}

      <div className="topology-graph-container">

        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={nodeTypes}
          fitView
          nodesConnectable={false}
        >

          <Background />

          <Controls />

          {showMinimap && (
            <MiniMap />
          )}

        </ReactFlow>

      </div>


      {/* =====================================================
          LEGEND
      ====================================================== */}

      <div className="topology-legend">

        <div className="topology-legend-item">

          <span className="legend-line data-flow" />

          <span>
            Data Flow
          </span>

        </div>


        <div className="topology-legend-item">

          <span className="legend-line monitoring-flow" />

          <span>
            Monitoring / State
          </span>

        </div>

      </div>

    </div>
  );
}
